/* Generated by tools/build_lines.py from picks/g17.txt. Every line is from: NCERT XII (old) Unit 7. Do not edit by hand. */
(function () {
  const R = window.RES;
  R.addLines("g17", "NCERT XII (old) Unit 7", [{"sec": "Occurrence","ids": [398,399],"t": "Group 17 (halogens, \"salt producers\"): F, Cl, Br, I, At, Ts.","exc": false,"tab": false,"src": "p15","page": 28,"o": "Fluorine, chlorine, bromine, iodine, astatine and tennessine are members of Group 17. These are collectively known as the halogens (Greek halo means salt and genes means born i.e., salt producers)."},{"sec": "Occurrence","ids": [400,401,402,403],"t": "Highly reactive non-metals; very similar to one another (like groups 1, 2), with regular gradation.","exc": false,"tab": false,"src": "p15","page": 28,"o": "The halogens are highly reactive non-metallic elements. Like Groups 1 and 2, the elements of Group 17 show great similarity amongst themselves. That much similarity is not found in the elements of other groups of the periodic table. Also, there is a regular gradation in their physical and chemical properties."},{"sec": "Occurrence","ids": [404],"t": "At and Ts are radioactive.","exc": false,"tab": false,"src": "p15","page": 28,"o": "Astatine and tennessine are radioactive elements."},{"sec": "Occurrence","ids": [406],"t": "F: insoluble fluorides, fluorspar CaF2, cryolite Na3AlF6, fluoroapatite 3Ca3(PO4)2·CaF2.","exc": false,"tab": false,"src": "p15","page": 28,"o": "Fluorine is present mainly as insoluble fluorides (fluorspar CaF2, cryolite Na3AlF6 and fluoroapatite 3Ca3(PO4)2.CaF2) and small quantities are present in soil, river water plants and bones and teeth of animals."},{"sec": "Occurrence","ids": [407],"t": "Sea water: Na, K, Mg, Ca halides, mainly NaCl (2.5% by mass).","exc": false,"tab": false,"src": "p15","page": 28,"o": "Sea water contains chlorides, bromides and iodides of sodium, potassium, magnesium and calcium, but is mainly sodium chloride solution (2.5% by mass)."},{"sec": "Occurrence","ids": [408],"t": "Dried-sea deposits: NaCl, carnallite KCl·MgCl2·6H2O.","exc": false,"tab": false,"src": "p15","page": 28,"o": "The deposits of dried up seas contain these compounds, e.g., sodium chloride and carnallite, KCl.MgCl2.6H2O."},{"sec": "Occurrence","ids": [409],"t": "I: seaweeds (up to 0.5% iodine); Chile saltpetre (up to 0.2% NaIO3).","exc": false,"tab": false,"src": "p15","page": 28,"o": "Certain forms of marine life contain iodine in their systems; various seaweeds, for example, contain upto 0.5% of iodine and Chile saltpetre contains upto 0.2% of sodium iodate."},{"sec": "Atomic properties","ids": [420],"t": "Smallest atoms in their periods (maximum effective nuclear charge).","exc": false,"tab": false,"src": "p15","page": 29,"o": "The halogens have the smallest atomic radii in their respective periods due to maximum effective nuclear charge."},{"sec": "Atomic properties","ids": [421],"t": "F is extremely small.","exc": false,"tab": false,"src": "p15","page": 29,"o": "The atomic radius of fluorine like the other elements of second period is extremely small."},{"sec": "Atomic properties","ids": [422],"t": "Radii increase F → I.","exc": false,"tab": false,"src": "p15","page": 29,"o": "Atomic and ionic radii increase from fluorine to iodine due to increasing number of quantum shells."},{"sec": "Atomic properties","ids": [423,424,425],"t": "Very high ∆iH (little tendency to lose electrons); decreases down the group.","exc": false,"tab": false,"src": "p15","page": 29,"o": "They have little tendency to lose electron. Thus they have very high ionisation enthalpy. Due to increase in atomic size, ionisation enthalpy decreases down the group."},{"sec": "Atomic properties","ids": [426,427],"t": "Most negative ∆egH in each period (one electron short of a noble gas).","exc": false,"tab": false,"src": "p15","page": 29,"o": "Halogens have maximum negative electron gain enthalpy in the corresponding periods. This is due to the fact that the atoms of these elements have only one electron less than stable noble gas configurations."},{"sec": "Atomic properties","ids": [428],"t": "∆egH becomes less negative down the group.","exc": false,"tab": false,"src": "p15","page": 29,"o": "Electron gain enthalpy of the elements of the group becomes less negative down the group."},{"sec": "Atomic properties","ids": [429,430,431],"t": "**∆egH(F) is less negative than ∆egH(Cl)**: small F, strong repulsion in compact 2p.","exc": true,"tab": false,"src": "p15","page": 29,"o": "However, the negative electron gain enthalpy of fluorine is less than that of chlorine. It is due to small size of fluorine atom. As a result, there are strong interelectronic repulsions in the relatively small 2p orbitals of fluorine and thus, the incoming electron does not experience much attraction."},{"sec": "Atomic properties","ids": [431],"t": "Table 7.8: Electron gain enthalpy/kJ mol^–1 F –333, Cl –349, Br –325, I –296. Bond dissociation enthalpy/kJ mol^–1 F2 158.8, Cl2 242.6, Br2 192.8, I2 151.1. E^⊖/V 2.87, 1.36, 1.09, 0.54. ∆HydH(X^–)/kJ mol^–1 515, 381, 347, 305.","exc": false,"tab": true,"src": "p15","page": 29,"o": "Table 7.8: Electron gain enthalpy/kJ mol^–1 F –333, Cl –349, Br –325, I –296. Bond dissociation enthalpy/kJ mol^–1 F2 158.8, Cl2 242.6, Br2 192.8, I2 151.1. E^⊖/V 2.87, 1.36, 1.09, 0.54. ∆HydH(X^–)/kJ mol^–1 515, 381, 347, 305."},{"sec": "Atomic properties","ids": [434,435],"t": "EN decreases down the group; **F is the most electronegative element**.","exc": false,"tab": false,"src": "p15","page": 30,"o": "The electronegativity decreases down the group. Fluorine is the most electronegative element in the periodic table."},{"sec": "Atomic properties","ids": [438,439],"t": "Small size, high Zeff: they readily accept one electron.","exc": false,"tab": false,"src": "p15","page": 30,"o": "Halogens have the smallest size in their respective periods and therefore high effective nuclear charge. As a consequence, they readily accept one electron to acquire noble gas electronic configuration."},{"sec": "Atomic properties","ids": [440,442,443],"t": "**F2 is a stronger oxidant than Cl2 despite less negative ∆egH**: low F–F bond enthalpy and high hydration enthalpy of F^–.","exc": true,"tab": false,"src": "p15","page": 30,"o": "Although electron gain enthalpy of fluorine is less negative as compared to chlorine, fluorine is a stronger oxidising agent than chlorine. It is due to (i) low enthalpy of dissociation of F-F bond. (ii) high hydration enthalpy of F^–."},{"sec": "Atomic properties","ids": [444],"t": "Physical properties vary smoothly.","exc": false,"tab": false,"src": "p15","page": 30,"o": "Halogens display smooth variations in their physical properties."},{"sec": "Physical properties","ids": [445,446],"t": "F2, Cl2 gases; Br2 liquid; I2 solid; m.p./b.p. increase with Z.","exc": false,"tab": false,"src": "p15","page": 30,"o": "Fluorine and chlorine are gases, bromine is a liquid and iodine is a solid. Their melting and boiling points steadily increase with atomic number."},{"sec": "Physical properties","ids": [447,448],"t": "All coloured: absorb visible light (outer electrons excited).","exc": false,"tab": false,"src": "p15","page": 30,"o": "All halogens are coloured. This is due to absorption of radiations in visible region which results in the excitation of outer electrons to higher energy level."},{"sec": "Physical properties","ids": [449,450],"t": "**F2 yellow, Cl2 greenish yellow, Br2 red, I2 violet.**","exc": false,"tab": false,"src": "p15","page": 30,"o": "By absorbing different quanta of radiation, they display different colours. For example, F2, has yellow, Cl2, greenish yellow, Br2, red and I2, violet colour."},{"sec": "Physical properties","ids": [451,452],"t": "F2 and Cl2 react with water; Br2 and I2 are sparingly soluble in water but dissolve in CHCl3, CCl4, CS2, hydrocarbons (coloured solutions).","exc": false,"tab": false,"src": "p15","page": 30,"o": "Fluorine and chlorine react with water. Bromine and iodine are only sparingly soluble in water but are soluble in various organic solvents such as chloroform, carbon tetrachloride, carbon disulphide and hydrocarbons to give coloured solutions."},{"sec": "Physical properties","ids": [453],"t": "**Bond enthalpy anomaly: F–F < Cl–Cl**; then Cl–Cl > Br–Br > I–I. Reason: large lone-pair repulsion in compact F2.","exc": true,"tab": false,"src": "p15","page": 30,"o": "One curious anomaly is the smaller enthalpy of dissociation of F2 compared to that of Cl2 whereas X-X bond dissociation enthalpies from chlorine onwards show the expected trend: Cl–Cl > Br–Br > I–I. A reason for this anomaly is the relatively large electron-electron repulsion among the lone pairs in F2 molecule where they are much closer to each other than in case of Cl2."},{"sec": "Oxidation states and reactivity","ids": [432,433],"t": "All show –1; Cl, Br, I also +1, +3, +5, +7.","exc": false,"tab": false,"src": "p15","page": 30,"o": "All the halogens exhibit –1 oxidation state. However, chlorine, bromine and iodine exhibit + 1, + 3, + 5 and + 7 oxidation states also."},{"sec": "Oxidation states and reactivity","ids": [454],"t": "Higher states of Cl, Br, I mainly in combination with F and O (interhalogens, oxides, oxoacids).","exc": false,"tab": false,"src": "p15","page": 31,"o": "The higher oxidation states of chlorine, bromine and iodine are realised mainly when the halogens are in combination with the small and highly electronegative fluorine and oxygen atoms. e.g., in interhalogens, oxides and oxoacids."},{"sec": "Oxidation states and reactivity","ids": [455],"t": "+4 and +6 occur in oxides and oxoacids of Cl and Br.","exc": false,"tab": false,"src": "p15","page": 31,"o": "The oxidation states of +4 and +6 occur in the oxides and oxoacids of chlorine and bromine."},{"sec": "Oxidation states and reactivity","ids": [456,457],"t": "**F shows only –1**: no d orbitals, most electronegative.","exc": true,"tab": false,"src": "p15","page": 31,"o": "The fluorine atom has no d orbitals in its valence shell and therefore cannot expand its octet. Being the most electronegative, it exhibits only –1 oxidation state."},{"sec": "Oxidation states and reactivity","ids": [458,459],"t": "All highly reactive; form halides with metals and non-metals.","exc": false,"tab": false,"src": "p15","page": 31,"o": "All the halogens are highly reactive. They react with metals and non-metals to form halides."},{"sec": "Oxidation states and reactivity","ids": [460,461],"t": "Reactivity decreases down the group; strong oxidising nature from ready electron acceptance.","exc": false,"tab": false,"src": "p15","page": 31,"o": "The reactivity of the halogens decreases down the group. The ready acceptance of an electron is the reason for the strong oxidising nature of halogens."},{"sec": "Oxidation states and reactivity","ids": [462,463],"t": "**F2 is the strongest oxidising halogen**; a halogen oxidises halide ions of higher Z.","exc": false,"tab": false,"src": "p15","page": 31,"o": "F2 is the strongest oxidising halogen and it oxidises other halide ions in solution or even in the solid phase. In general, a halogen oxidises halide ions of higher atomic number."},{"sec": "Oxidation states and reactivity","ids": [464],"t": "F2 + 2X^– → 2F^– + X2 (X = Cl, Br or I); Cl2 + 2X^– → 2Cl^– + X2 (X = Br or I); Br2 + 2I^– → 2Br^– + I2","exc": false,"tab": false,"src": "p15","page": 31,"o": "F2 + 2X^– → 2F^– + X2 (X = Cl, Br or I); Cl2 + 2X^– → 2Cl^– + X2 (X = Br or I); Br2 + 2I^– → 2Br^– + I2"},{"sec": "Oxidation states and reactivity","ids": [465,466],"t": "F2 oxidises water to O2; Cl2 and Br2 give HX + HOX; **I2 + water is non-spontaneous**.","exc": false,"tab": false,"src": "p15","page": 31,"o": "Fluorine oxidises water to oxygen whereas chlorine and bromine react with water to form corresponding hydrohalic and hypohalous acids. The reaction of iodine with water is nonspontaneous."},{"sec": "Oxidation states and reactivity","ids": [467],"t": "I^– is oxidised by O2 in acid: the reverse of the F2 reaction.","exc": true,"tab": false,"src": "p15","page": 31,"o": "In fact, I^– can be oxidised by oxygen in acidic medium; just the reverse of the reaction observed with fluorine."},{"sec": "Oxidation states and reactivity","ids": [468],"t": "2F2(g) + 2H2O(l) → 4H^+(aq) + 4F^–(aq) + O2(g); X2(g) + H2O(l) → HX(aq) + HOX(aq) (X = Cl or Br); 4I^–(aq) + 4H^+(aq) + O2(g) → 2I2(s) + 2H2O(l)","exc": false,"tab": true,"src": "p15","page": 31,"o": "2F2(g) + 2H2O(l) → 4H^+(aq) + 4F^–(aq) + O2(g); X2(g) + H2O(l) → HX(aq) + HOX(aq) (X = Cl or Br); 4I^–(aq) + 4H^+(aq) + O2(g) → 2I2(s) + 2H2O(l)"},{"sec": "Anomalous behaviour of fluorine","ids": [469,470],"t": "F: ∆iH, EN, E° higher than the trend predicts; radii, m.p., b.p., bond dissociation enthalpy and ∆egH lower.","exc": true,"tab": false,"src": "p15","page": 31,"o": "For example, ionisation enthalpy, electronegativity, and electrode potentials are all higher for fluorine than expected from the trends set by other halogens. Also, ionic and covalent radii, m.p. and b.p., enthalpy of bond dissociation and electron gain enthalpy are quite lower than expected."},{"sec": "Anomalous behaviour of fluorine","ids": [471],"t": "F is anomalous: small size, highest EN, low F–F bond enthalpy, no d orbitals.","exc": true,"tab": false,"src": "p15","page": 31,"o": "The anomalous behaviour of fluorine is due to its small size, highest electronegativity, low F-F bond dissociation enthalpy, and non availability of d orbitals in valence shell."},{"sec": "Anomalous behaviour of fluorine","ids": [472],"t": "Most F reactions are exothermic (small, strong bonds).","exc": false,"tab": false,"src": "p15","page": 31,"o": "Most of the reactions of fluorine are exothermic (due to the small and strong bond formed by it with other elements)."},{"sec": "Anomalous behaviour of fluorine","ids": [473],"t": "**F forms only one oxoacid (HOF).**","exc": true,"tab": false,"src": "p15","page": 31,"o": "It forms only one oxoacid while other halogens form a number of oxoacids."},{"sec": "Anomalous behaviour of fluorine","ids": [474,475,476,477],"t": "**HF is a liquid (b.p. 293 K)**, because of strong H-bonding; other HX are gases.","exc": true,"tab": false,"src": "p15","page": 31,"o": "Hydrogen fluoride is a liquid (b.p. 293 K) due to strong hydrogen bonding. Hydrogen bond is formed in HF due to small size and high electronegativity of fluorine. Other hydrogen halides which have bigger size and less electronegativity are gases."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [478,479],"t": "All form HX; affinity for H decreases F → I; HX dissolve to give hydrohalic acids.","exc": false,"tab": false,"src": "p15","page": 32,"o": "They all react with hydrogen to give hydrogen halides but affinity for hydrogen decreases from fluorine to iodine. Hydrogen halides dissolve in water to form hydrohalic acids."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [481],"t": "**Acid strength HF < HCl < HBr < HI**; HX stability decreases (H–F > H–Cl > H–Br > H–I bond enthalpy).","exc": false,"tab": false,"src": "p15","page": 32,"o": "The acidic strength of these acids varies in the order: HF < HCl < HBr < HI. The stability of these halides decreases down the group due to decrease in bond (H–X) dissociation enthalpy in the order: H–F > H–Cl > H–Br > H–I."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [481],"t": "Halogens form many oxides, mostly unstable.","exc": false,"tab": false,"src": "p15","page": 32,"o": "Halogens form many oxides with oxygen but most of them are unstable."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [482,483],"t": "F forms OF2 and O2F2; **only OF2 is thermally stable at 298 K**. They are oxygen fluorides (F more electronegative); strong fluorinating agents.","exc": true,"tab": false,"src": "p15","page": 32,"o": "Fluorine forms two oxides OF2 and O2F2. However, only OF2 is thermally stable at 298 K. These oxides are essentially oxygen fluorides because of the higher electronegativity of fluorine than oxygen. Both are strong fluorinating agents."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [484],"t": "O2F2 oxidises Pu to PuF6 (removes Pu from spent nuclear fuel).","exc": false,"tab": false,"src": "p15","page": 32,"o": "O2F2 oxidises plutonium to PuF6 and the reaction is used in removing plutonium as PuF6 from spent nuclear fuel."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [485],"t": "Cl, Br, I oxides: oxidation states +1 to +7.","exc": false,"tab": false,"src": "p15","page": 32,"o": "Chlorine, bromine and iodine form oxides in which the oxidation states of these halogens range from +1 to +7."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [486],"t": "**Oxide stability: I > Cl > Br.** I–O oxides are stabilised by bond polarisability.","exc": true,"tab": false,"src": "p15","page": 32,"o": "A combination of kinetic and thermodynamic factors lead to the generally decreasing order of stability of oxides formed by halogens, I > Cl > Br. Higher stability of oxides of iodine is due to greater polarisability of bond between iodine and oxygen."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [487,488],"t": "Cl–O multiple bonding (via d orbitals) increases stability.","exc": false,"tab": false,"src": "p15","page": 32,"o": "In the case of chlorine, multiple bond formation between chlorine and oxygen takes place due to availability of d–orbitals. This leads to increase in stability."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [489],"t": "Br lacks both, so Br oxides are least stable. Higher oxides are more stable than lower.","exc": false,"tab": false,"src": "p15","page": 32,"o": "Bromine lacks both the characteristics hence stability of oxides of bromine is least. The higher oxides of halogens tend to be more stable than the lower ones."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [490,491],"t": "Cl2O, ClO2, Cl2O6, Cl2O7: highly reactive oxidants, tend to explode. ClO2 bleaches paper pulp and textiles; water treatment.","exc": false,"tab": false,"src": "p15","page": 32,"o": "Chlorine oxides, Cl2O, ClO2, Cl2O6 and Cl2O7 are highly reactive oxidising agents and tend to explode. ClO2 is used as a bleaching agent for paper pulp and textiles and in water treatment."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [492,493],"t": "**Br oxides (Br2O, BrO2, BrO3) are the least stable halogen oxides** (middle-row anomaly); exist only at low T; very powerful oxidants.","exc": true,"tab": false,"src": "p15","page": 32,"o": "The bromine oxides, Br2O, BrO2, BrO3 are the least stable halogen oxides (middle row anomally) and exist only at low temperatures. They are very powerful oxidising agents."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [494,495],"t": "I2O4, I2O5, I2O7: insoluble solids, decompose on heating. **I2O5 estimates CO.**","exc": false,"tab": false,"src": "p15","page": 32,"o": "The iodine oxides, I2O4, I2O5, I2O7 are insoluble solids and decompose on heating. I2O5 is a very good oxidising agent and is used in the estimation of carbon monoxide."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [496,497],"t": "Halogens + metals → halides (e.g. Br2 + Mg → MgBr2).","exc": false,"tab": false,"src": "p15","page": 32,"o": "(iii) Reactivity towards metals: Halogens react with metals to form metal halides. For example, bromine reacts with magnesium to give magnesium bromide. 2020-21"},{"sec": "Hydrogen halides, oxides, metal halides","ids": [498],"t": "Ionic character: MF > MCl > MBr > MI. Halides of a higher oxidation state are more covalent.","exc": false,"tab": false,"src": "p15","page": 33,"o": "The ionic character of the halides decreases in the order MF > MCl > MBr > MI where M is a monovalent metal. If a metal exhibits more than one oxidation state, the halides in higher oxidation state will be more covalent than the one in lower oxidation state."},{"sec": "Hydrogen halides, oxides, metal halides","ids": [499],"t": "SnCl4, PbCl4, SbCl5, UF6 are more covalent than SnCl2, PbCl2, SbCl3, UF4.","exc": false,"tab": false,"src": "p15","page": 33,"o": "For example, SnCl4, PbCl4, SbCl5 and UF6 are more covalent than SnCl2, PbCl2, SbCl3 and UF4 respectively."},{"sec": "Interhalogen types and positive oxidation states","ids": [500],"t": "Interhalogens XX′, XX′3, XX′5, XX′7 (X larger, X′ smaller).","exc": false,"tab": false,"src": "p15","page": 33,"o": "Halogens combine amongst themselves to form a number of compounds known as interhalogens of the types XX′, XX3′, XX5′ and XX7′ where X is a larger size halogen and X′ is smaller size halogen."},{"sec": "Interhalogen types and positive oxidation states","ids": [501,503,504],"t": "F only –1 (no positive state); others +1, +3, +5, +7 using d orbitals.","exc": true,"tab": false,"src": "p15","page": 33,"o": "Fluorine exhibits only –1 oxidation state whereas other halogens exhibit + 1, + 3, + 5 and + 7 oxidation states also. Fluorine is the most electronegative element and cannot exhibit any positive oxidation state. Other halogens have d orbitals and therefore, can expand their octets and show + 1, + 3, + 5 and + 7 oxidation states also."},{"sec": "Chlorine","ids": [507,508],"t": "Cl2: MnO2 + 4HCl → MnCl2 + Cl2 + 2H2O","exc": false,"tab": false,"src": "p15","page": 33,"o": "By heating manganese dioxide with concentrated hydrochloric acid. MnO2 + 4HCl → MnCl2 + Cl2 + 2H2O"},{"sec": "Chlorine","ids": [508],"t": "Or NaCl + conc. H2SO4 instead of HCl: 4NaCl + MnO2 + 4H2SO4 → MnCl2 + 4NaHSO4 + 2H2O + Cl2","exc": false,"tab": false,"src": "p15","page": 33,"o": "However, a mixture of common salt and concentrated H2SO4 is used in place of HCl. 4NaCl + MnO2 + 4H2SO4 → MnCl2 + 4NaHSO4 + 2H2O + Cl2"},{"sec": "Chlorine","ids": [508],"t": "2KMnO4 + 16HCl → 2KCl + 2MnCl2 + 8H2O + 5Cl2","exc": false,"tab": false,"src": "p15","page": 33,"o": "By the action of HCl on potassium permanganate. 2KMnO4 + 16HCl → 2KCl + 2MnCl2 + 8H2O + 5Cl2"},{"sec": "Chlorine","ids": [508],"t": "**Deacon's process**: HCl oxidised by air over CuCl2 at 723 K.","exc": false,"tab": false,"src": "p15","page": 33,"o": "Deacon's process: By oxidation of hydrogen chloride gas by atmospheric oxygen in the presence of CuCl2 (catalyst) at 723 K."},{"sec": "Chlorine","ids": [508],"t": "4HCl + O2 → 2Cl2 + 2H2O (CuCl2)","exc": false,"tab": true,"src": "p15","page": 33,"o": "4HCl + O2 → 2Cl2 + 2H2O (CuCl2)"},{"sec": "Chlorine","ids": [508,509],"t": "Electrolysis of brine: Cl2 at the anode.","exc": false,"tab": false,"src": "p15","page": 33,"o": "Electrolytic process: Chlorine is obtained by the electrolysis of brine (concentrated NaCl solution). Chlorine is liberated at anode."},{"sec": "Chlorine","ids": [510],"t": "Also a by-product of many industries.","exc": false,"tab": false,"src": "p15","page": 33,"o": "It is also obtained as a by–product in many chemical industries."},{"sec": "Chlorine","ids": [511,512],"t": "Cl2: greenish-yellow, pungent, suffocating; ~2.5× heavier than air.","exc": false,"tab": false,"src": "p15","page": 34,"o": "It is a greenish yellow gas with pungent and suffocating odour. It is about 2-5 times heavier than air."},{"sec": "Chlorine","ids": [513],"t": "Easily liquefied (greenish-yellow liquid, b.p. 239 K); soluble in water.","exc": false,"tab": false,"src": "p15","page": 34,"o": "It can be liquefied easily into greenish yellow liquid which boils at 239 K. It is soluble in water."},{"sec": "Chlorine","ids": [514],"t": "Chlorine reacts with a number of metals and non-metals to form chlorides. 2Al + 3Cl2 → 2AlCl3; P4 + 6Cl2 → 4PCl3; 2Na + Cl2 → 2NaCl; S8 + 4Cl2 → 4S2Cl2; 2Fe + 3Cl2 → 2FeCl3","exc": false,"tab": false,"src": "p15","page": 34,"o": "Chlorine reacts with a number of metals and non-metals to form chlorides. 2Al + 3Cl2 → 2AlCl3; P4 + 6Cl2 → 4PCl3; 2Na + Cl2 → 2NaCl; S8 + 4Cl2 → 4S2Cl2; 2Fe + 3Cl2 → 2FeCl3"},{"sec": "Chlorine","ids": [514,515],"t": "Great affinity for H: takes H from compounds, forming HCl.","exc": false,"tab": false,"src": "p15","page": 34,"o": "It has great affinity for hydrogen. It reacts with compounds containing hydrogen to form HCl."},{"sec": "Chlorine","ids": [515],"t": "H2 + Cl2 → 2HCl; H2S + Cl2 → 2HCl + S; C10H16 + 8Cl2 → 16HCl + 10C","exc": false,"tab": true,"src": "p15","page": 34,"o": "H2 + Cl2 → 2HCl; H2S + Cl2 → 2HCl + S; C10H16 + 8Cl2 → 16HCl + 10C"},{"sec": "Chlorine","ids": [515],"t": "**Cold dilute alkali: chloride + hypochlorite. Hot concentrated: chloride + chlorate.**","exc": false,"tab": false,"src": "p15","page": 34,"o": "With cold and dilute alkalies chlorine produces a mixture of chloride and hypochlorite but with hot and concentrated alkalies it gives chloride and chlorate."},{"sec": "Chlorine","ids": [515],"t": "2NaOH + Cl2 → NaCl + NaOCl + H2O (cold and dilute); 6NaOH + 3Cl2 → 5NaCl + NaClO3 + 3H2O (hot and conc.)","exc": false,"tab": false,"src": "p15","page": 34,"o": "2NaOH + Cl2 → NaCl + NaOCl + H2O (cold and dilute); 6NaOH + 3Cl2 → 5NaCl + NaClO3 + 3H2O (hot and conc.)"},{"sec": "Chlorine","ids": [515],"t": "Dry slaked lime → bleaching powder: 2Ca(OH)2 + 2Cl2 → Ca(OCl)2 + CaCl2 + 2H2O","exc": false,"tab": false,"src": "p15","page": 34,"o": "With dry slaked lime it gives bleaching powder. 2Ca(OH)2 + 2Cl2 → Ca(OCl)2 + CaCl2 + 2H2O"},{"sec": "Chlorine","ids": [515],"t": "Bleaching powder: Ca(OCl)2·CaCl2·Ca(OH)2·2H2O.","exc": false,"tab": false,"src": "p15","page": 34,"o": "The composition of bleaching powder is Ca(OCl)2.CaCl2.Ca(OH)2.2H2O."},{"sec": "Chlorine","ids": [516],"t": "Saturated hydrocarbons: substitution; unsaturated: addition.","exc": false,"tab": false,"src": "p15","page": 34,"o": "Chlorine reacts with hydrocarbons and gives substitution products with saturated hydrocarbons and addition products with unsaturated hydrocarbons."},{"sec": "Chlorine","ids": [517],"t": "CH4 + Cl2 → CH3Cl + HCl (UV); C2H4 + Cl2 → C2H4Cl2 (room temp.)","exc": false,"tab": false,"src": "p15","page": 34,"o": "CH4 + Cl2 → CH3Cl + HCl (UV); C2H4 + Cl2 → C2H4Cl2 (room temp.)"},{"sec": "Chlorine","ids": [517],"t": "Chlorine water loses colour on standing (HCl + HOCl); HOCl gives nascent O, the source of oxidising and bleaching power.","exc": false,"tab": false,"src": "p15","page": 34,"o": "Chlorine water on standing loses its yellow colour due to the formation of HCl and HOCl. Hypochlorous acid (HOCl) so formed, gives nascent oxygen which is responsible for oxidising and bleaching properties of chlorine."},{"sec": "Chlorine","ids": [518,519,520],"t": "Cl2 oxidises Fe^2+ → Fe^3+, sulphite → sulphate, SO2 → SO3 (H2SO4 in water), I2 → iodate (HIO3).","exc": false,"tab": false,"src": "p15","page": 34,"o": "Chlorine oxidises ferrous to ferric and sulphite to sulphate. Chlorine oxidises sulphur dioxide to sulphur trioxide and iodine to iodate. In the presence of water they form sulphuric acid and iodic acid respectively."},{"sec": "Chlorine","ids": [520],"t": "2FeSO4 + H2SO4 + Cl2 → Fe2(SO4)3 + 2HCl; Na2SO3 + Cl2 + H2O → Na2SO4 + 2HCl; SO2 + 2H2O + Cl2 → H2SO4 + 2HCl; I2 + 6H2O + 5Cl2 → 2HIO3 + 10HCl","exc": false,"tab": false,"src": "p15","page": 34,"o": "2FeSO4 + H2SO4 + Cl2 → Fe2(SO4)3 + 2HCl; Na2SO3 + Cl2 + H2O → Na2SO4 + 2HCl; SO2 + 2H2O + Cl2 → H2SO4 + 2HCl; I2 + 6H2O + 5Cl2 → 2HIO3 + 10HCl"},{"sec": "Chlorine","ids": [520,521,522],"t": "**Cl2 bleaches by oxidation**, needs moisture; **bleaching is permanent**.","exc": false,"tab": false,"src": "p15","page": 34,"o": "Chlorine is a powerful bleaching agent; bleaching action is due to oxidation. It bleaches vegetable or organic matter in the presence of moisture. Bleaching effect of chlorine is permanent."},{"sec": "Chlorine","ids": [523],"t": "Cl2 + H2O → 2HCl + O; Coloured substance + O → Colourless substance","exc": false,"tab": false,"src": "p15","page": 34,"o": "Cl2 + H2O → 2HCl + O; Coloured substance + O → Colourless substance"},{"sec": "Chlorine","ids": [525],"t": "Cl2 + hot conc. NaOH is disproportionation: 0 → –1 and +5.","exc": true,"tab": false,"src": "p15","page": 35,"o": "Yes, chlorine from zero oxidation state is changed to –1 and +5 oxidation states."},{"sec": "Chlorine","ids": [534],"t": "Cl2 uses: bleaching wood pulp, cotton, textiles; extracting Au, Pt; dyes, drugs, CCl4, CHCl3, DDT, refrigerants; sterilising water; phosgene COCl2, tear gas CCl3NO2, mustard gas ClCH2CH2SCH2CH2Cl.","exc": false,"tab": false,"src": "p15","page": 35,"o": "It is used (i) for bleaching woodpulp (required for the manufacture of paper and rayon), bleaching cotton and textiles, (ii) in the extraction of gold and platinum (iii) in the manufacture of dyes, drugs and organic compounds such as CCl4, CHCl3, DDT, refrigerants, etc. (iv) in sterilising drinking water and (v) preparation of poisonous gases such as phosgene (COCl2), tear gas (CCl3NO2), mustard gas (ClCH2CH2SCH2CH2Cl)."},{"sec": "Hydrogen chloride","ids": [528,529],"t": "HCl lab: NaCl + H2SO4 → NaHSO4 + HCl (420 K); NaHSO4 + NaCl → Na2SO4 + HCl (823 K)","exc": false,"tab": false,"src": "p15","page": 35,"o": "In laboratory, it is prepared by heating sodium chloride with concentrated sulphuric acid. NaCl + H2SO4 → NaHSO4 + HCl (420K); NaHSO4 + NaCl → Na2SO4 + HCl (823K)"},{"sec": "Hydrogen chloride","ids": [529],"t": "Dried with conc. H2SO4.","exc": false,"tab": false,"src": "p15","page": 35,"o": "HCl gas can be dried by passing through concentrated sulphuric acid."},{"sec": "Hydrogen chloride","ids": [530,531],"t": "HCl: colourless, pungent; b.p. 189 K; f.p. 159 K (white crystalline solid).","exc": false,"tab": false,"src": "p15","page": 35,"o": "It is a colourless and pungent smelling gas. It is easily liquefied to a colourless liquid (b.p.189 K) and freezes to a white crystalline solid (f.p. 159 K)."},{"sec": "Hydrogen chloride","ids": [532],"t": "Extremely soluble; HCl + H2O → H3O^+ + Cl^–; Ka = 10^7 (hydrochloric acid).","exc": false,"tab": false,"src": "p15","page": 35,"o": "It is extremely soluble in water and ionises as follows: HCl(g) + H2O(l) → H3O^+(aq) + Cl^–(aq); Ka = 10^7. Its aqueous solution is called hydrochloric acid."},{"sec": "Hydrogen chloride","ids": [533],"t": "Large Ka: strong acid.","exc": false,"tab": false,"src": "p15","page": 35,"o": "High value of dissociation constant (Ka) indicates that it is a strong acid in water."},{"sec": "Hydrogen chloride","ids": [534],"t": "NH3 + HCl → NH4Cl (white fumes).","exc": false,"tab": false,"src": "p15","page": 35,"o": "It reacts with NH3 and gives white fumes of NH4Cl. NH3 + HCl → NH4Cl"},{"sec": "Hydrogen chloride","ids": [534],"t": "**Aqua regia: 3 parts conc. HCl + 1 part conc. HNO3**; dissolves Au, Pt.","exc": false,"tab": false,"src": "p15","page": 35,"o": "When three parts of concentrated HCl and one part of concentrated HNO3 are mixed, aqua regia is formed which is used for dissolving noble metals, e.g., gold, platinum."},{"sec": "Hydrogen chloride","ids": [534],"t": "Au + 4H^+ + NO3^– + 4Cl^– → AuCl4^– + NO + 2H2O; 3Pt + 16H^+ + 4NO3^– + 18Cl^– → 3PtCl6^2– + 4NO + 8H2O","exc": false,"tab": true,"src": "p15","page": 35,"o": "Au + 4H^+ + NO3^– + 4Cl^– → AuCl4^– + NO + 2H2O; 3Pt + 16H^+ + 4NO3^– + 18Cl^– → 3PtCl6^2– + 4NO + 8H2O"},{"sec": "Hydrogen chloride","ids": [535],"t": "Decomposes salts of weaker acids: Na2CO3 + 2HCl → 2NaCl + H2O + CO2; NaHCO3 + HCl → NaCl + H2O + CO2; Na2SO3 + 2HCl → 2NaCl + H2O + SO2","exc": false,"tab": false,"src": "p15","page": 36,"o": "Hydrochloric acid decomposes salts of weaker acids, e.g., carbonates, hydrogencarbonates, sulphites, etc. Na2CO3 + 2HCl → 2NaCl + H2O + CO2; NaHCO3 + HCl → NaCl + H2O + CO2; Na2SO3 + 2HCl → 2NaCl + H2O + SO2"},{"sec": "Hydrogen chloride","ids": [535,537],"t": "**Fe + HCl gives FeCl2, not FeCl3**: the H2 liberated prevents FeCl3 formation. Fe + 2HCl → FeCl2 + H2","exc": true,"tab": false,"src": "p15","page": 36,"o": "When HCl reacts with finely powdered iron, it forms ferrous chloride and not ferric chloride. Its reaction with iron produces H2. Fe + 2HCl → FeCl2 + H2. Liberation of hydrogen prevents the formation of ferric chloride."},{"sec": "Hydrogen chloride","ids": [538],"t": "HCl uses: Cl2, NH4Cl, glucose from corn starch; glue from bones; purifying bone black; medicine; lab reagent.","exc": false,"tab": false,"src": "p15","page": 36,"o": "It is used (i) in the manufacture of chlorine, NH4Cl and glucose (from corn starch), (ii) for extracting glue from bones and purifying bone black, (iii) in medicine and as a laboratory reagent."},{"sec": "Oxoacids of halogens","ids": [535],"t": "Table 7.10: Halic (I) acid (hypohalous acid): HOF, HOCl, HOBr, HOI. Halic (III) acid (halous acid): only HOClO (chlorous acid). Halic (V) acid (halic acid): HOClO2, HOBrO2, HOIO2. Halic (VII) acid (perhalic acid): HOClO3, HOBrO3, HOIO3.","exc": false,"tab": true,"src": "p15","page": 36,"o": "Table 7.10: Halic (I) acid (hypohalous acid): HOF, HOCl, HOBr, HOI. Halic (III) acid (halous acid): only HOClO (chlorous acid). Halic (V) acid (halic acid): HOClO2, HOBrO2, HOIO2. Halic (VII) acid (perhalic acid): HOClO3, HOBrO3, HOIO3."},{"sec": "Oxoacids of halogens","ids": [539],"t": "**F forms only HOF** (hypofluorous acid), owing to high EN and small size.","exc": true,"tab": false,"src": "p15","page": 36,"o": "Due to high electronegativity and small size, fluorine forms only one oxoacid, HOF known as fluoric (I) acid or hypofluorous acid."},{"sec": "Oxoacids of halogens","ids": [540,541,542],"t": "Other halogen oxoacids: most can't be isolated pure; stable only in solution or as salts.","exc": false,"tab": false,"src": "p15","page": 36,"o": "The other halogens form several oxoacids. Most of them cannot be isolated in pure state. They are stable only in aqueous solutions or in the form of their salts."},{"sec": "Oxoacids of halogens","ids": [679],"t": "Halogen is the central atom with one X–OH; some have X=O bonds.","exc": false,"tab": false,"src": "p15","page": 43,"o": "In the structures of these oxoacids, halogen is the central atom which is bonded in each case with one OH bond as X–OH. In some cases X = O bonds are also found."},{"sec": "Interhalogen compounds","ids": [544,545],"t": "Interhalogens XX′, XX′3, XX′5, XX′7: X larger and more electropositive than X′.","exc": false,"tab": false,"src": "p15","page": 37,"o": "When two different halogens react with each other, interhalogen compounds are formed. They can be assigned general compositions as XX′, XX3′, XX5′ and XX7′ where X is halogen of larger size and X′ of smaller size and X is more electropositive than X′."},{"sec": "Interhalogen compounds","ids": [546,547,548],"t": "Atoms per molecule rise with the radius ratio X/X′; I/F is largest, hence **IF7**.","exc": false,"tab": false,"src": "p15","page": 37,"o": "As the ratio between radii of X and X′ increases, the number of atoms per molecule also increases. Thus, iodine (VII) fluoride should have maximum number of atoms as the ratio of radii between I and F should be maximum. That is why its formula is IF7 (having maximum number of atoms)."},{"sec": "Interhalogen compounds","ids": [549],"t": "Made by direct combination, or halogen + lower interhalogen.","exc": false,"tab": false,"src": "p15","page": 37,"o": "The interhalogen compounds can be prepared by the direct combination or by the action of halogen on lower interhalogen compounds."},{"sec": "Interhalogen compounds","ids": [550],"t": "I2 + Cl2 → 2ICl (equimolar); Cl2 + 3F2 → 2ClF3 (excess F2, 573 K); Cl2 + F2 → 2ClF (equal volume, 437 K); I2 + 3Cl2 → 2ICl3 (excess Cl2); Br2 + 3F2 → 2BrF3 (diluted with water); Br2 + 5F2 → 2BrF5 (excess F2)","exc": false,"tab": true,"src": "p15","page": 37,"o": "I2 + Cl2 → 2ICl (equimolar); Cl2 + 3F2 → 2ClF3 (excess F2, 573 K); Cl2 + F2 → 2ClF (equal volume, 437 K); I2 + 3Cl2 → 2ICl3 (excess Cl2); Br2 + 3F2 → 2BrF3 (diluted with water); Br2 + 5F2 → 2BrF5 (excess F2)"},{"sec": "Interhalogen compounds","ids": [551],"t": "Table 7.11, XX′: ClF colourless gas; BrF pale brown gas; IF detected spectroscopically (very unstable); BrCl gas; ICl ruby red solid (α-form), brown red solid (β-form); IBr black solid.","exc": false,"tab": true,"src": "p15","page": 37,"o": "Table 7.11, XX′: ClF colourless gas; BrF pale brown gas; IF detected spectroscopically (very unstable); BrCl gas; ICl ruby red solid (α-form), brown red solid (β-form); IBr black solid."},{"sec": "Interhalogen compounds","ids": [551],"t": "Table 7.11, XX′3: ClF3 colourless gas, bent T-shaped; BrF3 yellow green liquid, bent T-shaped; IF3 yellow powder, bent T-shaped (?); ICl3 orange solid, bent T-shaped (?), dimerises as Cl–bridged dimer (I2Cl6).","exc": false,"tab": true,"src": "p15","page": 37,"o": "Table 7.11, XX′3: ClF3 colourless gas, bent T-shaped; BrF3 yellow green liquid, bent T-shaped; IF3 yellow powder, bent T-shaped (?); ICl3 orange solid, bent T-shaped (?), dimerises as Cl–bridged dimer (I2Cl6)."},{"sec": "Interhalogen compounds","ids": [551],"t": "Table 7.11, XX′5 and XX′7: IF5 colourless gas but solid below 77 K, square pyramidal; BrF5 colourless liquid, square pyramidal; ClF5 colourless liquid, square pyramidal; IF7 colourless gas, pentagonal bipyramidal.","exc": false,"tab": true,"src": "p15","page": 37,"o": "Table 7.11, XX′5 and XX′7: IF5 colourless gas but solid below 77 K, square pyramidal; BrF5 colourless liquid, square pyramidal; ClF5 colourless liquid, square pyramidal; IF7 colourless gas, pentagonal bipyramidal."},{"sec": "Interhalogen compounds","ids": [552,553],"t": "All covalent and diamagnetic; volatile solids or liquids at 298 K **except ClF (gas)**.","exc": false,"tab": false,"src": "p15","page": 38,"o": "These are all covalent molecules and are diamagnetic in nature. They are volatile solids or liquids at 298 K except ClF which is a gas."},{"sec": "Interhalogen compounds","ids": [554],"t": "Properties intermediate between the parent halogens, but m.p./b.p. slightly higher than expected.","exc": false,"tab": false,"src": "p15","page": 38,"o": "Their physical properties are intermediate between those of constituent halogens except that their m.p. and b.p. are a little higher than expected."},{"sec": "Interhalogen compounds","ids": [556,557],"t": "**Interhalogens are more reactive than halogens (except F2)**: X–X′ is weaker than X–X.","exc": true,"tab": false,"src": "p15","page": 38,"o": "In general, interhalogen compounds are more reactive than halogens (except fluorine). This is because X–X′ bond in interhalogens is weaker than X–X bond in halogens except F–F bond."},{"sec": "Interhalogen compounds","ids": [558],"t": "Hydrolysis: halide from the smaller halogen; from the larger, hypohalite (XX′), halite (XX′3), halate (XX′5), perhalate (XX′7).","exc": false,"tab": false,"src": "p15","page": 38,"o": "All these undergo hydrolysis giving halide ion derived from the smaller halogen and a hypohalite (when XX′), halite (when XX′3), halate (when XX′5) and perhalate (when XX′7) anion derived from the larger halogen."},{"sec": "Interhalogen compounds","ids": [559],"t": "XX′ + H2O → HX′ + HOX","exc": false,"tab": false,"src": "p15","page": 38,"o": "XX′ + H2O → HX′ + HOX"},{"sec": "Interhalogen compounds","ids": [560],"t": "**XX′3 bent T, XX′5 square pyramidal, IF7 pentagonal bipyramidal.**","exc": false,"tab": false,"src": "p15","page": 38,"o": "The XX3′ compounds have the bent ‘T’ shape, XX5′ compounds square pyramidal and IF7 has pentagonal bipyramidal structures."},{"sec": "Interhalogen compounds","ids": [562,563,564],"t": "BrF3: Br has 7 valence electrons; 3 bond pairs + 2 lone pairs.","exc": false,"tab": false,"src": "p15","page": 38,"o": "The central atom Br has seven electrons in the valence shell. Three of these will form electron-pair bonds with three fluorine atoms leaving behind four electrons. Thus, there are three bond pairs and two lone pairs."},{"sec": "Interhalogen compounds","ids": [565,566],"t": "Trigonal bipyramid arrangement; both lone pairs equatorial (lp–lp and lp–bp > bp–bp).","exc": false,"tab": false,"src": "p15","page": 38,"o": "According to VSEPR theory, these will occupy the corners of a trigonal bipyramid. The two lone pairs will occupy the equatorial positions to minimise lone pair-lone pair and the bond pair-lone pair repulsions which are greater than the bond pair-bond pair repulsions."},{"sec": "Interhalogen compounds","ids": [567,568],"t": "Axial F bend toward the equatorial F: **slightly bent T**.","exc": false,"tab": false,"src": "p15","page": 38,"o": "In addition, the axial fluorine atoms will be bent towards the equatorial fluorine in order to minimise the lone-pair-lone pair repulsions. The shape would be that of a slightly bent ‘T’."},{"sec": "Interhalogen compounds","ids": [569,570],"t": "Non-aqueous solvents; very useful fluorinating agents.","exc": false,"tab": false,"src": "p15","page": 38,"o": "These compounds can be used as non aqueous solvents. Interhalogen compounds are very useful fluorinating agents."},{"sec": "Interhalogen compounds","ids": [571],"t": "ClF3, BrF3 make UF6 for uranium enrichment: U(s) + 3ClF3(l) → UF6(g) + 3ClF(g)","exc": false,"tab": false,"src": "p15","page": 38,"o": "ClF3 and BrF3 are used for the production of UF6 in the enrichment of U. U(s) + 3ClF3(l) → UF6(g) + 3ClF(g)"},{"sec": "Interhalogen compounds","ids": [704],"t": "ICl is more reactive than I2.","exc": false,"tab": false,"src": "p15","page": 45,"o": "Thus, ICl is more reactive than I2."}]);
})();
